<script setup>
import {ref,computed,watch,onMounted,onUnmounted} from 'vue'
import {Search,ShoppingBag,Heart,UserRound,ArrowRight,ArrowUpRight,ChevronDown,ChevronRight,ChevronLeft,Menu,X,Truck,ShieldCheck,RotateCcw,Headphones,Grid2X2,Shirt,House,Sparkles,Bike,Zap,Check,Plus,Minus,Package,Mail,Instagram,Star,SlidersHorizontal,Leaf} from 'lucide-vue-next'
import ProductCard from './components/ProductCard.vue'
import DevBackendStatus from './components/DevBackendStatus.vue'
const isDevelopment = import.meta.env.DEV
import {products,categories,image,money,cartTotal,filteredProducts} from './shop'
function readStorage(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
const savedCart=readStorage('nova-cart',[])
const cart=ref(Array.isArray(savedCart)?savedCart.filter(l=>products.some(p=>p.id===l.id)&&Number.isInteger(l.quantity)&&l.quantity>0).map(l=>({...products.find(p=>p.id===l.id),quantity:Math.min(l.quantity,products.find(p=>p.id===l.id).stock)})):[])
const savedFavorites=readStorage('nova-favorites',[])
const favorites=ref(Array.isArray(savedFavorites)?savedFavorites.filter(id=>products.some(p=>p.id===id)):[])
const view=ref('home'),query=ref(''),category=ref('Tout découvrir'),sort=ref('featured'),cartOpen=ref(false),mobileMenu=ref(false),selected=ref(null),quantity=ref(1),toast=ref(''),email=ref(''),subscribed=ref(false),newsletterError=ref(''),slide=ref(0),checkout=ref(false),account=ref(false)
const icons=[Grid2X2,Headphones,Shirt,House,Sparkles,Bike]
const slides=[{eyebrow:'LA SÉLECTION QUI CHANGE TOUT',title:'Un peu de vous.\nBeaucoup de style.',text:'Des objets bien pensés, des essentiels qui durent.\nDécouvrez ce qui rend votre quotidien extraordinaire.',image:'photo-1546435770-a3e426bf472b',label:'Le son, en toute liberté.',detail:'Casque Studio · Dès 89 €',category:'High-tech'}, {eyebrow:'VOTRE PROCHAINE PIÈCE PRÉFÉRÉE',title:'Les détails font\nla différence.',text:'Des accessoires choisis pour leur caractère.\nUne nouvelle façon d’affirmer votre style.',image:'photo-1524805444758-089113d48a6d',label:'Le temps du beau.',detail:'Montre Essential · Dès 119 €',category:'Mode & accessoires'}, {eyebrow:'PENSÉ POUR VOTRE INTÉRIEUR',title:'Bien chez vous.\nTout simplement.',text:'Des lignes douces et des pièces singulières.\nFaites de votre intérieur un endroit qui vous ressemble.',image:'photo-1567538096630-e0c55bd6374c',label:'Votre nouvelle place préférée.',detail:'Fauteuil Nordic · Dès 249 €',category:'Maison & déco'}]
const hero=computed(()=>slides[slide.value]),count=computed(()=>cart.value.reduce((s,l)=>s+l.quantity,0)),total=computed(()=>cartTotal(cart.value)),shipping=computed(()=>total.value>=10000||!cart.value.length?0:490)
const results=computed(()=>filteredProducts({query:query.value,category:category.value,sort:sort.value,favorites:view.value==='favorites'?favorites.value:null}))
watch(cart,v=>{try{localStorage.setItem('nova-cart',JSON.stringify(v.map(({id,quantity})=>({id,quantity}))))}catch{}},{deep:true})
watch(favorites,v=>{try{localStorage.setItem('nova-favorites',JSON.stringify(v))}catch{}},{deep:true})
let toastTimer,previousFocus
function notify(text){toast.value=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',3200)}
function toggleFavorite(id){favorites.value=favorites.value.includes(id)?favorites.value.filter(x=>x!==id):[...favorites.value,id]}
function add(product,amount=1){const existing=cart.value.find(l=>l.id===product.id);if((existing?.quantity||0)+amount>product.stock){notify('Quantité maximale disponible atteinte.');return}if(existing)existing.quantity+=amount;else cart.value.push({...product,quantity:amount});notify(`${product.name} ajouté au panier`)}
function change(id,delta){const line=cart.value.find(l=>l.id===id);if(!line)return;if(line.quantity+delta>line.stock){notify('Quantité maximale disponible atteinte.');return}line.quantity+=delta;if(line.quantity<=0)cart.value=cart.value.filter(l=>l.id!==id)}
function browse(name='Tout découvrir'){category.value=name;view.value='catalog';mobileMenu.value=false;window.scrollTo({top:0,behavior:'smooth'})}
function home(){view.value='home';query.value='';category.value='Tout découvrir';window.scrollTo({top:0,behavior:'smooth'})}
function search(){view.value='catalog';mobileMenu.value=false;window.scrollTo({top:0,behavior:'smooth'})}
function openProduct(product){selected.value=product;quantity.value=1}
function closeOverlays(){cartOpen.value=false;selected.value=null;checkout.value=false;account.value=false}
const overlay=computed(()=>cartOpen.value||selected.value||checkout.value||account.value)
watch(overlay,async value=>{document.body.style.overflow=value?'hidden':'';if(value){previousFocus=document.activeElement;setTimeout(()=>document.querySelector('[role="dialog"] button')?.focus(),0)}else previousFocus?.focus()})
function keyboard(event){if(event.key==='Escape'){closeOverlays();mobileMenu.value=false}if(event.key==='Tab'&&overlay.value){const nodes=[...document.querySelectorAll('[role="dialog"] button,[role="dialog"] input,[role="dialog"] a')].filter(el=>!el.disabled);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}}
function subscribe(){if(!email.value.trim()||! /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value)){newsletterError.value='Saisissez une adresse e-mail valide.';return}newsletterError.value='';subscribed.value=true}
onMounted(()=>document.addEventListener('keydown',keyboard));onUnmounted(()=>{document.removeEventListener('keydown',keyboard);clearTimeout(toastTimer);document.body.style.overflow=''})
</script>
<template>
<DevBackendStatus v-if="isDevelopment"/>
<a class="skip-link" href="#main">Aller au contenu</a>
<div class="announcement"><div class="container announcement-inner"><span><Truck :size="14"/> Livraison offerte dès 100 € d’achat</span><span>De belles trouvailles. Tous les jours. <span class="tiny-star">✦</span></span><span class="demo-label">Boutique démo <i></i> FR / EUR</span></div></div>
<header class="header"><div class="container header-main"><button class="logo" aria-label="NovaShop, accueil" @click="home">nova<span>shop</span><i>✦</i></button><form class="search" role="search" @submit.prevent="search"><Search :size="19"/><input v-model="query" aria-label="Rechercher un produit" placeholder="Une envie, un produit, une marque…"/><button type="submit">Rechercher <ArrowRight :size="15"/></button></form><div class="header-actions"><button class="header-icon account-button" aria-label="Mon compte" @click="account=true"><UserRound :size="22"/><span>Mon compte</span></button><button class="header-icon" aria-label="Mes favoris" @click="view='favorites';query='';category='Tout découvrir'"><Heart :size="22"/><small v-if="favorites.length">{{favorites.length}}</small></button><span class="action-divider"></span><button class="header-icon" aria-label="Ouvrir le panier" @click="cartOpen=true"><ShoppingBag :size="22"/><small>{{count}}</small></button><button class="header-icon mobile-toggle" aria-label="Ouvrir la navigation" :aria-expanded="mobileMenu" @click="mobileMenu=!mobileMenu"><Menu/></button></div></div>
<div class="nav-border"><nav class="container navigation" aria-label="Navigation principale"><button class="category-trigger" @click="mobileMenu=!mobileMenu" :aria-expanded="mobileMenu"><Grid2X2 :size="18"/> Toutes les catégories <ChevronDown :size="15"/></button><div class="nav-links"><button :class="{current:view==='home'}" @click="home">Accueil</button><button :class="{current:view==='catalog'}" @click="browse()">La boutique</button><button @click="browse();sort='price-up'">Les bonnes affaires <span class="nav-pill">HOT</span></button><button @click="browse();sort='featured'">Nos nouveautés</button></div><button class="nav-editorial" @click="browse('Maison & déco')">L’inspiration du moment <ArrowUpRight :size="15"/></button></nav></div>
<div v-if="mobileMenu" class="container dropdown"><button v-for="(item,i) in categories" :key="item.name" @click="browse(item.name)"><component :is="icons[i]" :size="18"/>{{item.name}}<ChevronRight :size="15"/></button></div>
</header>
<main id="main">
<template v-if="view==='home'">
<section class="container hero-layout"><aside class="category-sidebar"><div class="sidebar-label">À CHAQUE ENVIE, SON UNIVERS</div><button v-for="(item,i) in categories.slice(1)" :key="item.name" @click="browse(item.name)"><component :is="icons[i+1]" :size="20"/><span>{{item.name}}</span><ChevronRight :size="14"/></button><div class="sidebar-bottom"><span class="mini-spark">✦</span><div>Une sélection qui a du sens.<small>Choisie avec soin, pour vous.</small></div></div></aside><div class="hero"><div class="hero-noise"></div><div class="hero-copy"><span class="eyebrow"><span></span>{{hero.eyebrow}}</span><h1>{{hero.title}}</h1><p>{{hero.text}}</p><button class="button button-dark" @click="browse(hero.category)">Explorer la collection <ArrowUpRight :size="18"/></button><div class="hero-social"><div class="avatars"><img v-for="(id,i) in ['photo-1438761681033-6461ffad8d80','photo-1506794778202-cad84cf45f1d','photo-1472099645785-5658abf4ff4e']" :key="id" :src="image(id,70)" alt="" :style="{zIndex:3-i}"/></div><div><span class="stars">★★★★★</span><small>Des essentiels à aimer au quotidien</small></div></div></div><div class="hero-visual"><div class="hero-ring"></div><span class="hero-large-star">✦</span><img :key="hero.image" class="hero-product" :src="image(hero.image,1000)" :alt="hero.label" fetchpriority="high"/><div class="floating-tag"><span>LA PIÈCE DU MOMENT</span><strong>{{hero.label}}</strong><small>{{hero.detail}}</small><ArrowUpRight :size="19"/></div><div class="offer-sticker">Jusqu’à<strong>−30<span>%</span></strong><small>SUR LA SÉLECTION</small></div></div><div class="hero-pagination"><button v-for="(_,i) in slides" :key="i" :aria-label="`Afficher la sélection ${i+1}`" :aria-pressed="slide===i" :class="{active:slide===i}" @click="slide=i"></button><span>0{{slide+1}} / 03</span></div></div></section>
<section class="container benefits-strip" aria-label="Services envisagés"><div><Truck/><span>Livraison offerte<small>Dès 100 € d’achat</small></span></div><div><ShieldCheck/><span>Paiement sécurisé<small>Intégration Stripe prévue</small></span></div><div><RotateCcw/><span>Retours simplifiés<small>Politique à venir</small></span></div><div><Headphones/><span>À votre écoute<small>Un accompagnement humain</small></span></div></section>
<section class="container section"><div class="section-heading"><div><span class="eyebrow coral">LES ENVIES N’ATTENDENT PAS</span><h2><Zap class="coral-icon" :size="24"/>Les offres à saisir<span class="heading-dot">.</span></h2></div><div class="section-heading-right"><span class="selection-label">Petits prix, grandes découvertes</span><button class="text-link" @click="browse();sort='price-up'">Voir les offres <ArrowRight :size="16"/></button></div></div><div class="product-grid four"><ProductCard v-for="p in products.slice(0,4)" :key="p.id" :product="p" :favorite="favorites.includes(p.id)" @favorite="toggleFavorite" @add="add" @open="openProduct"/></div></section>
<section class="container section universes"><div class="section-heading"><div><span class="eyebrow muted">UN MONDE DE POSSIBILITÉS</span><h2>À chacun son univers<span class="heading-dot">.</span></h2></div><button class="text-link" @click="browse()">Tout explorer <ArrowRight :size="16"/></button></div><div class="universe-grid"><button v-for="(cat,i) in [{name:'High-tech',sub:'Connecté à vos envies',image:'photo-1505740420928-5e560c06d30e',count:'Audio, photo & accessoires'},{name:'Mode & accessoires',sub:'Le style, au quotidien',image:'photo-1523275335684-37898b6baf30',count:'Montres, sacs & essentiels'},{name:'Maison & déco',sub:'Votre intérieur, autrement',image:'photo-1616486338812-3dadae4b4ace',count:'Mobilier, lumière & objets'}]" :key="cat.name" class="universe-card" @click="browse(cat.name)"><img :src="image(cat.image,900)" :alt="cat.name" loading="lazy"/><div><span>0{{i+1}} — {{cat.name}}</span><h3>{{cat.sub}}</h3><small>{{cat.count}}</small></div><span class="universe-arrow"><ArrowUpRight :size="20"/></span></button></div></section>
<section class="editorial-band"><div class="container editorial-inner"><div><span class="eyebrow">MOINS D’ORDINAIRE. PLUS DE VOUS.</span><h2>Bien choisis.<br/>Vraiment vous.</h2><p>Pas besoin de tout. Juste de ce qui compte.<br/>Des pièces qui trouvent naturellement leur place dans votre vie.</p><button class="button button-light" @click="browse()">Trouver mon prochain coup de cœur <ArrowUpRight :size="17"/></button></div><div class="editorial-image"><img :src="image('photo-1495474472287-4d71bcdd2085',900)" alt="Un moment de calme autour d’un café" loading="lazy"/><span class="editorial-note">Les petites choses.<br/><i>Les grands bonheurs.</i></span></div><span class="editorial-spark">✦</span></div></section>
<section class="container section"><div class="section-heading"><div><span class="eyebrow coral">FRAÎCHEMENT DÉNICHÉS</span><h2>Du nouveau, pour vous<span class="heading-dot">.</span></h2></div><button class="text-link" @click="browse()">Voir la sélection <ArrowRight :size="16"/></button></div><div class="product-grid four"><ProductCard v-for="p in products.slice(4,8)" :key="p.id" :product="p" :favorite="favorites.includes(p.id)" @favorite="toggleFavorite" @add="add" @open="openProduct"/></div></section>
<section class="container promo-grid"><div class="promo-card audio-promo"><div><span class="eyebrow">VOTRE BANDE-SON, PARTOUT</span><h2>Du son.<br/>Sans limites.</h2><button class="text-link" @click="browse('High-tech')">Découvrir l’audio <ArrowRight :size="17"/></button></div><img :src="image('photo-1608043152269-423dbba4e7e1',650)" alt="Enceinte nomade" loading="lazy"/></div><div class="promo-card style-promo"><div><span class="eyebrow">LES ESSENTIELS DU QUOTIDIEN</span><h2>Le bon style.<br/>Au bon moment.</h2><button class="text-link" @click="browse('Mode & accessoires')">Trouver mon style <ArrowRight :size="17"/></button></div><img :src="image('photo-1524805444758-089113d48a6d',650)" alt="Montre sur bracelet en cuir" loading="lazy"/></div></section>
<section class="container values"><div><Leaf :size="28"/><h3>Le choix du détail</h3><p>Une sélection pensée pour allier utilité, qualité et plaisir.</p></div><div><Package :size="28"/><h3>Simple, du début à la fin</h3><p>De la première découverte au panier, tout devient plus facile.</p></div><div><Heart :size="28"/><h3>Des envies qui comptent</h3><p>Gardez vos coups de cœur et retrouvez-les à tout moment.</p></div></section>
</template>
<section v-else class="container catalog section"><div class="breadcrumb"><button @click="home">Accueil</button><ChevronRight :size="13"/>{{view==='favorites'?'Mes favoris':'La boutique'}}</div><div class="section-heading"><div><span class="eyebrow coral">LA SÉLECTION NOVASHOP</span><h1>{{view==='favorites'?'Vos coups de cœur.':category==='Tout découvrir'?'Faites place à vos envies.':category}}</h1><p class="muted">{{results.length}} produit{{results.length>1?'s':''}} à découvrir{{query?` pour « ${query} »`:''}}</p></div><label class="sort"><SlidersHorizontal :size="17"/><select v-model="sort" aria-label="Trier les produits"><option value="featured">Notre sélection</option><option value="price-up">Prix croissant</option><option value="price-down">Prix décroissant</option></select></label></div><div class="filter-chips"><button v-for="cat in categories" :key="cat.name" :class="{active:category===cat.name}" @click="category=cat.name">{{cat.name}}</button></div><div v-if="results.length" class="product-grid four"><ProductCard v-for="p in results" :key="p.id" :product="p" :favorite="favorites.includes(p.id)" @favorite="toggleFavorite" @add="add" @open="openProduct"/></div><div v-else class="empty-state"><Search :size="40"/><h2>{{view==='favorites'?'Vos prochaines belles trouvailles vous attendent.':'Aucun produit trouvé.'}}</h2><p>Explorez la sélection ou essayez une autre recherche.</p><button class="button button-dark" @click="query='';browse()">Explorer la boutique <ArrowRight :size="17"/></button></div></section>
<section class="newsletter"><div class="container newsletter-inner"><div><span class="eyebrow">UN PEU DE NOVA DANS VOTRE BOÎTE MAIL</span><h2>Les bonnes nouvelles se partagent<span>✦</span></h2><p>Nouveautés, inspirations et jolies découvertes. Tout simplement.</p></div><form @submit.prevent="subscribe" novalidate><div class="newsletter-input"><Mail :size="18"/><input v-model="email" type="email" aria-label="Votre adresse e-mail" placeholder="Votre adresse e-mail" :disabled="subscribed" required/><button :disabled="subscribed" :aria-label="subscribed?'Inscription simulée terminée':'Simuler l’inscription'">{{subscribed?'C’est noté !':'Je m’inscris'}}<Check v-if="subscribed" :size="17"/><ArrowRight v-else :size="17"/></button></div><small :class="{'form-error':newsletterError}" aria-live="polite">{{newsletterError||(subscribed?'Démonstration : aucune adresse n’a été envoyée ni enregistrée.':'Aperçu du formulaire · Aucun e-mail envoyé dans cette démo.')}}</small></form></div></section>
</main>
<footer class="footer"><div class="container footer-top"><div class="footer-brand"><button class="logo" @click="home">nova<span>shop</span><i>✦</i></button><p>Un nouvel univers pour vos envies.<br/>Des découvertes choisies, un quotidien réinventé.</p><span class="footer-signature">Pensé avec soin. Choisi pour vous.</span></div><div><h3>Explorer</h3><button @click="browse()">Toute la boutique</button><button @click="browse('High-tech')">High-tech</button><button @click="browse('Mode & accessoires')">Mode & accessoires</button><button @click="browse('Maison & déco')">Maison & déco</button></div><div><h3>Votre NovaShop</h3><button @click="account=true">Mon compte</button><button @click="view='favorites';query='';category='Tout découvrir'">Mes favoris</button><button @click="cartOpen=true">Mon panier</button><button @click="notify('Le suivi des commandes sera disponible après connexion au backend.')">Suivre une commande</button></div><div><h3>Une question ?</h3><p>Notre espace d’aide arrive bientôt.</p><span class="footer-demo"><span></span>Version de démonstration</span><p class="footer-demo-copy">Catalogue fictif et panier local.<br/>Aucune commande réelle.</p></div></div><div class="container footer-bottom"><span>© {{new Date().getFullYear()}} NovaShop. Tous droits réservés.</span><span>Design & développement avec attention <span class="coral">✦</span></span><div class="payment-brands"><b>VISA</b><b class="mastercard">●●</b><b>stripe</b></div></div></footer>
<Transition name="toast"><div v-if="toast" class="toast-message" role="status"><Check :size="18"/>{{toast}}</div></Transition>
<Transition name="overlay"><div v-if="overlay" class="overlay" @click.self="closeOverlays">
<aside v-if="cartOpen" class="cart-drawer" role="dialog" aria-modal="true" aria-labelledby="cart-title"><div class="drawer-heading"><div><span class="eyebrow coral">VOS BELLES TROUVAILLES</span><h2 id="cart-title">Mon panier <span>({{count}})</span></h2></div><button class="icon-button" aria-label="Fermer le panier" @click="cartOpen=false"><X/></button></div><template v-if="cart.length"><div class="shipping-note"><Truck :size="18"/><span>{{total>=10000?'La livraison vous est offerte !':`Plus que ${money(10000-total)} pour la livraison offerte`}}</span><div><span :style="{width:Math.min(100,total/100)+'%'}"></span></div></div><div class="cart-lines"><article v-for="line in cart" :key="line.id" class="cart-line"><img :src="image(line.image,200)" :alt="line.name"/><div><small>{{line.brand}}</small><h3>{{line.name}}</h3><strong>{{money(line.price)}}</strong><div class="quantity"><button :aria-label="`Diminuer ${line.name}`" @click="change(line.id,-1)"><Minus :size="13"/></button><span>{{line.quantity}}</span><button :aria-label="`Augmenter ${line.name}`" @click="change(line.id,1)"><Plus :size="13"/></button></div></div><button class="remove-line" :aria-label="`Retirer ${line.name}`" @click="cart=cart.filter(l=>l.id!==line.id)"><X :size="15"/></button></article></div><div class="cart-summary"><div><span>Sous-total</span><strong>{{money(total)}}</strong></div><div><span>Livraison estimée</span><span>{{shipping?money(shipping):'Offerte'}}</span></div><div class="summary-total"><span>Total estimé</span><strong>{{money(total+shipping)}}</strong></div><button class="button button-dark" @click="cartOpen=false;checkout=true">Continuer <ArrowRight :size="18"/></button><small><ShieldCheck :size="13"/> Démonstration · Aucun paiement débité</small></div></template><div v-else class="empty-state"><ShoppingBag :size="44"/><h3>Tout commence par une envie.</h3><p>Votre panier attend ses premières trouvailles.</p><button class="button button-dark" @click="cartOpen=false;browse()">Découvrir la sélection <ArrowRight :size="16"/></button></div></aside>
<section v-else-if="selected" class="product-modal" role="dialog" aria-modal="true" aria-labelledby="product-title"><button class="modal-close icon-button" aria-label="Fermer la fiche produit" @click="selected=null"><X/></button><div class="modal-image"><img :src="image(selected.image,1000)" :alt="selected.name"/></div><div class="modal-info"><span class="eyebrow coral">{{selected.brand}}</span><h2 id="product-title">{{selected.name}}</h2><div class="rating"><Star :size="15" fill="currentColor"/>{{selected.rating}} <span>· {{selected.reviews}} avis illustratifs</span></div><div class="modal-price">{{money(selected.price)}} <del>{{money(selected.old)}}</del></div><p>Une pièce choisie pour son style et son utilité au quotidien. Retrouvez l’esprit NovaShop dans cet essentiel de la collection {{selected.category.toLowerCase()}}.</p><span class="stock"><span></span>En stock · {{selected.stock}} exemplaires dans la démo</span><div class="modal-buy"><div class="quantity"><button aria-label="Diminuer la quantité" :disabled="quantity===1" @click="quantity--"><Minus :size="16"/></button><span>{{quantity}}</span><button aria-label="Augmenter la quantité" :disabled="quantity===selected.stock" @click="quantity++"><Plus :size="16"/></button></div><button class="button button-dark" @click="add(selected,quantity)">Ajouter au panier <ShoppingBag :size="17"/></button></div><button class="text-link" @click="toggleFavorite(selected.id)"><Heart :size="17" :fill="favorites.includes(selected.id)?'currentColor':'none'"/>{{favorites.includes(selected.id)?'Dans mes favoris':'Garder dans mes favoris'}}</button><div class="modal-details"><span><Truck :size="17"/>Livraison offerte dès 100 €</span><span><ShieldCheck :size="17"/>Prix et stocks de démonstration</span></div></div></section>
<section v-else-if="checkout" class="info-modal" role="dialog" aria-modal="true" aria-labelledby="checkout-title"><button class="modal-close icon-button" aria-label="Fermer" @click="checkout=false"><X/></button><ShieldCheck :size="42" class="coral-icon"/><span class="eyebrow coral">APERÇU DU PARCOURS</span><h2 id="checkout-title">Vos envies sont presque à vous.</h2><p>Le paiement Stripe et la création de commande seront disponibles après connexion au backend Laravel. Aucun paiement n’est collecté dans cette démonstration.</p><div class="checkout-preview"><span>{{count}} article{{count>1?'s':''}} · Total estimé</span><strong>{{money(total+shipping)}}</strong></div><button class="button button-dark" @click="checkout=false;cartOpen=true">Revenir à mon panier <ArrowRight :size="16"/></button></section>
